import { $, api, escapeHtml, state, title, usableRoles } from '../core.js';

export function renderFoundation(page){
  const module=state.bundle.modules.find(item=>item.id===page)||{label:title(page),description:'This module is part of the Orbit foundation.',status:'foundation'};
  const extras={moderation:'Honeypot, exempt roles/users, one-hour message cleanup, warnings, AutoMod and cases.',roles:'Reaction roles, buttons, select menus, role groups and temporary roles.',tickets:'Category dropdowns, forms, staff routing, claiming, transfers and transcripts.',leveling:'Message/voice XP, cooldowns, role rewards, profiles and leaderboards.',automation:'Trigger → conditions → actions, using shared Orbit actions instead of one-off feature code.',scheduler:'Batch queue, recurring posts, templates, timezone handling, run history and future CSV import/export.',kofi:'Webhook-backed milestones and configurable Discord actions.',social:'Instagram, TikTok, YouTube, Twitch, Threads, Bluesky, Mastodon and RSS publishing + Social → Discord notifications.',logs:'Unified moderation, system, ticket, verification and configuration history.',diagnostics:'Discord permissions, role hierarchy, Turnstile, D1, queues, bindings and module health checks.'};
  $('#content').innerHTML=`<div class="eyebrow">${escapeHtml(module.status||'foundation')}</div><h1 class="page-title">${escapeHtml(module.label||title(page))}</h1><p class="page-intro">${escapeHtml(module.description||'')}</p><div class="empty"><span class="status ${escapeHtml(module.status||'foundation')}">${module.status==='roadmap'?'Roadmap':'Foundation laid'}</span><h2>The framework is here.</h2><p>${escapeHtml(extras[page]||'This page is intentionally present before its feature is activated so Orbit can grow without redesigning navigation or storage every release.')}</p><button class="btn secondary" type="button" disabled>Module activation coming next</button></div>`;
}
